// Récupérer les données de l'input (résultat de la requête HTTP Pipedrive)
// Pipedrive renvoie souvent les données dans une propriété "data"
const inputData = $input.first().json.data || $input.first().json;

const now = new Date();
const futureCohorts = [];

// Mapping des mois français pour la conversion
const months = {
  'janvier': 0, 'février': 1, 'mars': 2, 'avril': 3, 'mai': 4, 'juin': 5,
  'juillet': 6, 'août': 7, 'septembre': 8, 'octobre': 9, 'novembre': 10, 'décembre': 11
};

// Filtrer et traiter les stages
for (const stage of inputData) {
  // Vérification de sécurité si le nom existe
  if (stage.name && stage.name.startsWith('Cohorte')) {

    const title = stage.name.toLowerCase();

    // Regex pour capturer la date entre parenthèses ou dans le titre
    // Ex: "Cohorte 55 (12 février)" -> capture "12" et "février"
    const match = title.match(/(\d{1,2})\s+(janvier|février|mars|avril|mai|juin|juillet|août|septembre|octobre|novembre|décembre)/);

    if (match) {
      const day = parseInt(match[1]);
      const monthStr = match[2];
      const month = months[monthStr];

      // Gestion de l'année : Si on est en Décembre et la cohorte est en Janvier, c'est l'année prochaine
      let year = now.getFullYear();
      if (month < now.getMonth() && (now.getMonth() > 9)) { 
          year += 1; 
      }

      const cohortDate = new Date(year, month, day);

      // On ne garde que les dates futures (ou aujourd'hui)
      // On enlève 1 jour à "now" pour garder les cohortes du jour même
      const yesterday = new Date(now);
      yesterday.setDate(yesterday.getDate() - 1);

      if (cohortDate >= yesterday) {
        // Formatage propre pour l'email (ex: "Jeudi 12 février")
        const options = { weekday: 'long', day: 'numeric', month: 'long' };
        const formattedDate = cohortDate.toLocaleDateString('fr-FR', options);
        const finalString = formattedDate.charAt(0).toUpperCase() + formattedDate.slice(1);

        futureCohorts.push({
          stage_id: stage.id,
          nom_pipedrive: stage.name,
          date_iso: cohortDate.toISOString(), // Pour le tri informatique
          date_email: finalString, // Pour l'affichage dans le mail (ex: "Jeudi 12 février")
          jour_semaine: finalString.split(' ')[0] // ex: "Jeudi"
        });
      }
    }
  }
}

// Tri des cohortes par date (de la plus proche à la plus lointaine)
futureCohorts.sort((a, b) => new Date(a.date_iso) - new Date(b.date_iso));

return [{
  json: {
    cohortes_disponibles: futureCohorts
  }
}];

// 1. Récupérer tous les éléments qui arrivent (Partie 1, Partie 2...)
const allItems = $input.all();

// 2. Trier les fichiers par nom pour respecter l'ordre chronologique de Zoom
allItems.sort((a, b) => (a.json.name || "").localeCompare(b.json.name || ""));

// 3. Fusionner les textes
let finalTranscription = "";
allItems.forEach((item, index) => {
    // On cherche le texte dans la structure Gemini
    const text = item.json.text || item.json.candidates?.[0]?.content?.parts?.[0]?.text || "";
    if (text) {
        finalTranscription += `\n\n[--- PARTIE ${index + 1} DE L'APPEL ---]\n\n` + text;
    }
});

// 4. Récupérer les infos du prospect depuis le Webhook pour garder le contexte
const webhook = $('Webhook Telegram').item.json.query;

return {
    text: finalTranscription.trim(),
    metadata: {
        total_parts: allItems.length,
        prospect: webhook.prospect,
        email: webhook.email,
        date: webhook.date
    }
};

// ============================================================
// NŒUD : Formatage Final v8
// ============================================================

const data = $('Limit').first().json;
const signatureData = $('Fetch Signature').first().json;

// 1. Lecture des champs
let subject =
    data.subject ||
    data.Objet ||
    data.email_subject ||
    "Suivi de notre échange";

let bodyRaw =
    data.preview ||
    data.Corps ||
    data.email_body ||
    "";

// 2. Nettoyage du sujet
subject = subject
    .replace("✉️ Email envoyé :", "")
    .replace(/[#\*«»—]/g, "")
    .trim();

// 3. Nettoyage résiduel sécuritaire
bodyRaw = bodyRaw
    .replace(/\\\*/g, "*")
    .replace(/\\\[/g, "[")
    .replace(/\\\]/g, "]")
    .replace(/\\\(/g, "(")
    .replace(/\\\)/g, ")")
    .replace(/\\\-/g, "-")
    .replace(/\\\|/g, "|")
    .replace(/\\\\/g, "\\")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&")
    .replace(/\r\n/g, "\n")
    .replace(/Chaleureusement[\s\S]*$/i, "")
    .trim();

// 4. Conversion Markdown → HTML stylisé
function applyEducfinanceStyle(text) {
    if (!text || text.trim() === "") return "<i>Erreur : Le contenu du message est vide.</i>";

    let html = text
        // Titres
        .replace(/^#+\s+(.*)$/gm, '<div style="margin-top: 20px; margin-bottom: 10px; color: #1a1a1a;"><b>$1</b></div>')
        // Gras
        .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
        // Liens
        .replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2" style="color: #007BFF; text-decoration: underline;">$1</a>')
        // Listes à puces (Points noirs avec retrait)
        .replace(/^\s*[\-\*]\s+(.*)$/gm, (match, p1) => {
            return `<table role="presentation" border="0" cellspacing="0" cellpadding="0" style="margin-bottom: 6px; width: 100%; margin-left: 20px;">
                <tr>
                    <td style="vertical-align: top; width: 15px; color: #1a1a1a; font-weight: bold; font-size: 16px; line-height: 1.5;">•</td>
                    <td style="vertical-align: top; font-family: Arial, sans-serif; font-size: 16px; line-height: 1.5; color: #1a1a1a; padding-left: 5px;">${p1}</td>
                </tr>
            </table>`;
        });

    // Tableaux Markdown (Style élégant, lignes horizontales uniquement, centré)
    html = html.replace(/(?:\|.*\|\n)+/g, function(match) {
        const rows = match.trim().split('\n');
        // Centrage du tableau avec margin auto et largeur 90%
        let tableHtml = '<table style="width: 90%; border-collapse: collapse; margin: 25px auto; font-family: Arial, sans-serif; font-size: 14px; color: #444;">';

        rows.forEach((row, index) => {
            if (row.match(/^\|[\s\-\:]+\|/)) return; // Sauter la ligne de séparation Markdown

            const cells = row.split('|').filter(cell => cell.trim() !== '');
            tableHtml += '<tr>';

            cells.forEach(cell => {
                const cellContent = cell.trim();
                // Style des cellules : bordure basse uniquement, gris très clair
                const cellStyle = 'border-bottom: 1px solid #eeeeee; padding: 12px 8px; text-align: left;';

                if (index === 0) {
                    // Header : texte un peu plus sombre et gras
                    tableHtml += `<th style="${cellStyle} color: #1a1a1a; font-weight: bold; background-color: #fafafa;">${cellContent}</th>`;
                } else {
                    // Corps du tableau
                    tableHtml += `<td style="${cellStyle}">${cellContent}</td>`;
                }
            });
            tableHtml += '</tr>';
        });
        tableHtml += '</table>';
        return tableHtml;
    });

    // Gestion des paragraphes
    return html.split(/\n\n+/).map(para => {
        if (para.includes('<table') || para.includes('<div')) return para;
        return `<div style="margin-bottom: 14px; font-family: Arial, sans-serif; font-size: 16px; line-height: 1.6; color: #1a1a1a;">${para.replace(/\n/g, "<br>")}</div>`;
    }).join("");
}

// 5. Formule de clôture
const closingHtml = `<div style="margin-top: 20px; margin-bottom: 4px; font-family: Arial, sans-serif; font-size: 16px; line-height: 1.6; color: #1a1a1a;">Chaleureusement,</div>`;

// 6. Signature HTML complète
const signatureHtml = signatureData.data || `<br><div style="font-family: Arial, sans-serif; font-size: 14px; color: #333;"><b>Djamel-Eddine Bourouba</b><br>Ambassadeur Educfinance</div>`;

// 7. Signature pour CRM
const signaturePipedrive = `<br><div style="font-family: Arial, sans-serif; font-size: 13px; color: #555; border-top: 1px solid #eee; padding-top: 8px; margin-top: 8px;"><b>Djamel-Eddine Bourouba</b><br>Ambassadeur Educfinance</div>`;

// 8. Assemblage Final
const finalBody = applyEducfinanceStyle(bodyRaw);

const finalHtmlEmail = `<div style="font-family: Arial, sans-serif; font-size: 16px; line-height: 1.6; color: #1a1a1a; max-width: 650px; margin: 0 auto;">${finalBody}${closingHtml}${signatureHtml}</div>`;

const finalHtmlPipedrive = `<div style="font-family: Arial, sans-serif; font-size: 16px; line-height: 1.6; color: #1a1a1a; max-width: 650px;">${finalBody}${closingHtml}${signaturePipedrive}</div>`;

return {
    final_subject: subject,
    final_html: finalHtmlEmail,
    final_html_crm: finalHtmlPipedrive
};

// ============================================================
// NŒUD CODE : Construction du payload OpenRouter v3
// Nouveautés :
//   - Pré-traitement JS des variables de scoring et profil
//     → le LLM reçoit des signaux interprétés, pas du JSON brut
//   - Tableau des modules calculé en JS pur
//     → zéro calcul de dates demandé au LLM
// ============================================================

const profil   = $('Parsing variables du profiling').item.json;
const scoring  = $('Mettre en variable le scoring output').item.json;
const cohortes = $('Cohortes ouvertes').item.json.cohortes_disponibles;
const prospect = $('Prospect opty retrieval').item.json;

// ─── PRÉNOM — source prioritaire : title du nœud Prospect ────
// Format attendu : "Estelle Kamga" → extrait le premier mot
const prenomCRM = (prospect.title || '').split(' ')[0].trim();
const prenom    = prenomCRM || profil.identite?.prenom || "cher prospect";

// ─── DATE DE L'APPEL — depuis expected_close_date ────────────
const dateAppelRaw = prospect.expected_close_date || null;
const now          = new Date();
const TZ           = 'America/Toronto';

// Calcul de la référence temporelle relative
let referenceAppel = "tout à l'heure";
if (dateAppelRaw) {
  // Forcer l'interprétation en heure locale Toronto pour éviter le décalage UTC
  // "2026-02-24" → "2026-02-24T12:00:00" → midi local, jamais de glissement de jour
  const dateAppel = new Date(dateAppelRaw + 'T12:00:00');
  // Comparer les dates en ignorant l'heure
  const aujourdhuiStr = now.toLocaleDateString('fr-CA', { timeZone: TZ });
  const appelStr      = dateAppel.toLocaleDateString('fr-CA', { timeZone: TZ });

  if (appelStr === aujourdhuiStr) {
    // Même jour — adapter selon le moment de la journée actuel
    const heure = parseInt(now.toLocaleTimeString('fr-CA', { hour: '2-digit', hour12: false, timeZone: TZ }));
    if (heure < 12)        referenceAppel = "ce matin";
    else if (heure < 14)   referenceAppel = "ce midi";
    else if (heure < 18)   referenceAppel = "cet après-midi";
    else                   referenceAppel = "ce soir";
  } else {
    // Jour différent — hier ou date précise selon l'écart
    const diffMs   = now - dateAppel;
    const diffJours = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    if (diffJours === 1)      referenceAppel = "hier";
    else if (diffJours === 2) referenceAppel = "avant-hier";
    else                      referenceAppel = `le ${dateAppel.toLocaleDateString('fr-CA', { weekday: 'long', day: 'numeric', month: 'long', timeZone: TZ })}`;
  }
