// ─── NOUVEAUX CHAMPS — issus du profiling enrichi ────────────
const citations = profil.citations_verbatim || {};
const resumeConversationnel = profil.resume_conversationnel || '';

// ─── TRANSCRIPT BRUT — source primaire de vérité ─────────────
// Injecté directement pour que le LLM capte les nuances,
// corrections et évolutions de position en cours d'échange.
// Limite : 8000 chars début + 3000 chars fin (appels longs)
const transcriptRaw = $('Aggregate').item.json.text || '';
