// afin qu'il les cite avec les mots du prospect, pas du jargon

const frictions = [];

if (profil.situation_financiere?.dette_totale > 0)
  frictions.push(`Dette active de ${profil.situation_financiere.dette_totale}$ — sentiment de blocage avant d'investir`);

