  arguments_cibles.push(`Les FNB à frais zéro remplacent les fonds mutuels — économie directe et mesurable sur votre patrimoine`);

if (profil.objectifs?.retraite_age)
  arguments_cibles.push(`Un module entier sur la fiscalité au décaissement — structurer le retrait pour minimiser l'impôt à la retraite`);

if (profil.situation_financiere?.dette_totale > 0)
  arguments_cibles.push(`Le module Destination aborde la priorisation dette vs investissement — une décision claire, pas une intuition`);

if (profil.disponibilites?.contraintes_horaires)
  arguments_cibles.push(`Chaque rencontre live est enregistrée et disponible le lendemain matin — aucune séance perdue`);

