arguments_cibles.push(`Accès à vie à la formation et à la communauté — pas un cours à usage unique`);
arguments_cibles.push(`Plateforme de courtage à 0$ commission — l'autonomie sans les frais`);

// ─── PRÉ-TRAITEMENT 3 : Tableau des modules (calcul JS pur) ──
// Le LLM ne calcule AUCUNE date — il reçoit le HTML final prêt

function buildModuleTable(dateCohorte) {
  if (!dateCohorte) return null;

  const D = new Date(dateCohorte);
  const fmt = (date) => date.toLocaleDateString('fr-CA', {
