    return `<tr><td style="padding:6px 8px;">${m.nom}</td><td style="padding:6px 8px;">${liveStr}${note}</td><td style="padding:6px 8px;">${coursStr}</td></tr>`;
  }).join('\n');

  return `<table border="1" cellpadding="5" cellspacing="0" style="border-collapse:collapse; width:100%; border:1px solid #ddd; font-size:14px;">
<tr style="background:#f4f4f4;"><th style="padding:6px 8px;">Module</th><th style="padding:6px 8px;">Rencontre Live (20h00)</th><th style="padding:6px 8px;">Accès cours</th></tr>
${rows}
</table>`;
}

// Extraction de la date de cohorte selon le scénario
const scenario = scoring.scenario_logistique || '';
