FORMAT JSON :
{"Objet": "...", "Corps": "..."}`;

// ─── USER PROMPT ─────────────────────────────────────────────
const userPrompt = `Nous sommes le ${today}.

═══ SOURCE PRIMAIRE — TRANSCRIPT COMPLET DE L'APPEL ═══
(Lis attentivement. Ce que le prospect dit EN FIN D'APPEL prime sur le début.
