    data?.choices?.[0]?.message?.content ||  // OpenRouter
    data?.text ||                              // Gemini natif n8n
    (data?.content?.parts ? data.content.parts[0].text : "") ||  // Gemini API
    data?.Corps ||
    data?.preview ||
    "";

// 2. Nettoyage balises Markdown de code
rawText = rawText
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

// 3. Parse JSON → extraction Objet et Corps
let subject = "Suivi de notre échange";
let bodyMarkdown = rawText;

try {
    // Cas 1 : rawText est directement le JSON {"Objet":..., "Corps":...}
    const parsed = JSON.parse(rawText);
    if (parsed.Objet) subject = parsed.Objet;
    if (parsed.Corps) bodyMarkdown = parsed.Corps;
} catch (e) {
    // Cas 2 : rawText contient le JSON dans une string avec caractères autour
    try {
        const match = rawText.match(/\{[\s\S]*\}/);
        if (match) {
            const parsed2 = JSON.parse(match[0]);
            if (parsed2.Objet) subject = parsed2.Objet;
            if (parsed2.Corps) bodyMarkdown = parsed2.Corps;
        }
    } catch (e2) {
        // Cas 3 : pas de JSON — on garde rawText tel quel
    }
}

// 4. Nettoyage du sujet
subject = subject
    .replace("✉️ Email envoyé :", "")
    .replace(/[#\*«»—]/g, "")
    .trim();

// 5. Désescapement des doubles backslashes produits par n8n
bodyMarkdown = bodyMarkdown
    .replace(/\\\*/g, "*")
    .replace(/\\\[/g, "[")
    .replace(/\\\]/g, "]")
    .replace(/\\\(/g, "(")
    .replace(/\\\)/g, ")")
    .replace(/\\\-/g, "-")
    .replace(/\\\|/g, "|")
    .replace(/\\\\/g, "\\")
    .replace(/\r\n/g, "\n")
    .trim();

// 6. Suppression signature résiduelle
// (réinjectée proprement dans Formatage Final)
bodyMarkdown = bodyMarkdown
    .replace(/Chaleureusement[\s\S]*$/i, "")
    .replace(/Djamel-Eddine Bourouba[\s\S]*$/i, "")
    .replace(/Ambassadeur Educfinance[\s\S]*$/i, "")
    .replace(/Si vous pensez que l['']éducation[\s\S]*$/i, "")
    .trim();

// 7. Récupérer le modèle utilisé depuis la réponse OpenRouter
const modeleUtilise = $input.first().json.model || "modèle inconnu";

// 8. Sortie propre pour la boucle de révision
return {
    modele_utilise: modeleUtilise,
    subject: subject,
    preview: bodyMarkdown
};

