    const dated = cohorteStages
      .map(s => {
        const m = s.name.toLowerCase().match(/(\d{1,2})\s+([a-zàâéèêëîïôùûüç]+)/);
        if (!m) return null;
        const mo = monthMap[m[2]];
        if (mo === undefined) return null;
        const yr = (mo < now.getMonth()) ? now.getFullYear() + 1 : now.getFullYear();
        return { stage: s, date: new Date(yr, mo, parseInt(m[1])) };
      })
      .filter(Boolean)
      .filter(x => x.date >= now)
      .sort((a, b) => a.date - b.date);

    if (dated.length > 0) {
      match = dated[0].stage;
      matchMethod = "next_cohort_cas2";
    }
  }

  if (match && matchMethod !== "next_cohort_cas2") {
    resolvedStageId = match.id;
    matchMethod     = "date_match";
  } else if (match) {
    resolvedStageId = match.id;
  }
}

// ─── 6. OUTPUT ───────────────────────────────────────────────
return [{
  json: {
    deal_id:            dealId,
    stage_id:           resolvedStageId,
    stage_name_resolved: stages.find(s => s.id === resolvedStageId)?.name,
    match_method:       matchMethod,   // date_match | next_cohort_cas2 | fallback_suivi
    scenario_used:      scenario,
    date_input:         chosenDateRaw,
    is_cas1:            isCAS1,
    is_cas2:            isCAS2,
    stages_available:   stages.map(s => ({ id: s.id, name: s.name }))
  }
}];

// Résolution Deal Actif
// Cherche le premier item de Prospect opty retrieval dont data !== null
const items = $('Prospect opty retrieval').all();

const valid = items.find(i => 
  i.json.data !== null && 
  Array.isArray(i.json.data) && 
  i.json.data.length > 0
);

if (!valid) {
  throw new Error('[Résolution Deal Actif] Aucun deal actif trouvé dans Pipedrive pour ce prospect');
}

const deal = valid.json.data[0];

return [{
  json: {
    deal_id:    deal.id,
    person_id:  deal.person_id.value,
    org_id:     deal.org_id?.value ?? null,
    deal_title: deal.title,
    stage_id:   deal.stage_id,
    pipeline_id: deal.pipeline_id
  }
}];
